mapper.select:
SELECT A.ARTICLE_CODE AS articleCode, A.TITLE AS title, A.WRITER_CODE AS writer, U.NAME AS writerName, A.STATUS AS status, A.REGISTERED_AT AS registeredAt, A.VIEWS AS views, CASE WHEN WRITER_CODE=#{writerCode} THEN 1 ELSE 0 END AS isMyArticle FROM ARTICLE A INNER JOIN USERS U ON A.WRITER_CODE = U.USER_CODE WHERE 1=1
AND #{searchType} = #{searchKey}
ORDER BY #{sortBy} #{order}
